// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Set up: make this contract an admin (already done in constructor) and the ranked battle address
        // The constructor sets _rankedBattleAddress = address(this). So this contract can call addPoints.
        // Call addPoints to satisfy the require: msg.sender == _rankedBattleAddress
        c.addPoints(0, 100);

        // Now try to call updateWinnersPerPeriod with a new value
        // In the reference contract, it should succeed and set winnersPerPeriod to 5.
        // In the buggy contract, it will revert.
        uint256 initialWinnersPerPeriod = c.winnersPerPeriod();
        c.updateWinnersPerPeriod(5);
        uint256 finalWinnersPerPeriod = c.winnersPerPeriod();
        assertTrue(finalWinnersPerPeriod != initialWinnersPerPeriod, "winnersPerPeriod should have changed");
    }
}

