pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Call addPoints through the ranked battle address (which is this contract)
        c.addPoints(0, 1);
        // After the call, winnersPerPeriod should be 0 (unchanged, since updateWinnersPerPeriod was never called)
        // But in the buggy version, if updateWinnersPerPeriod had been called with some amount,
        // the bug would increment instead of set. However, we can observe that the correct contract
        // still has winnersPerPeriod == 0 because no admin changed it.
        // To trigger the actual divergence, we need to call updateWinnersPerPeriod.
        // But the problem statement says the difference is observable after addPoints completes.
        // Since addPoints doesn't call updateWinnersPerPeriod, the only way to see the difference
        // is that the buggy updateWinnersPerPeriod would have been called previously.
        // Let's set up a scenario: first call updateWinnersPerPeriod with 5 (should set to 5 in P,
        // but in M it adds 5 to current 0, so also 5). Then call updateWinnersPerPeriod with 3:
        // P sets to 3, M adds 3 to 5 => 8. Then call addPoints (irrelevant).
        // The difference: P.winnersPerPeriod() == 3, M.winnersPerPeriod() == 8.
        // Since we are testing against a deployed C, we need to assume we can distinguish.
        // Actually, we can just call updateWinnersPerPeriod(5) then updateWinnersPerPeriod(3)
        // and observe the value.
        // But the instruction says the difference is driven through addPoints. However,
        // addPoints doesn't touch winnersPerPeriod. So the only way is that the bug
        // is in updateWinnersPerPeriod, and we call it directly. The problem statement
        // might be imprecise. Let's just call updateWinnersPerPeriod directly and observe.
        // The instruction says "after a call to addPoints completes, the value differs"
        // but addPoints doesn't change it. Perhaps the intended scenario is that
        // updateWinnersPerPeriod is called somewhere else, but we can simulate by
        // calling it directly.
        // To comply with the instruction, we can first call updateWinnersPerPeriod(5)
        // (which sets to 5 in both), then updateWinnersPerPeriod(3) (which sets to 3 in P,
        // adds to 5 => 8 in M), then call addPoints (does nothing), then check winnersPerPeriod.
        c.updateWinnersPerPeriod(5);
        c.updateWinnersPerPeriod(3);
        c.addPoints(0, 1);
        // P: winnersPerPeriod == 3; M: winnersPerPeriod == 8
        assertTrue(c.winnersPerPeriod() == 3);
    }
}

