pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Non-admin address (not the deployer, not an admin)
        address nonAdmin = address(0x1234);
        vm.prank(nonAdmin);
        // Call addPoints; this will succeed for any caller (no access control)
        c.addPoints(1, 100);

        // Now the non-admin tries to change winnersPerPeriod
        bool ok;
        vm.prank(nonAdmin);
        try c.updateWinnersPerPeriod(5) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract (P) requires isAdmin[msg.sender], so the call reverts -> ok == false
        // The buggy version (M) removes the check, so the call succeeds -> ok == true and winnersPerPeriod becomes 5
        // Assert that the caller is NOT an admin, meaning the call should have reverted.
        // We read the current value of winnersPerPeriod to confirm divergence:
        // In reference, it stays as 2; in buggy, it is 5.
        assertTrue(c.winnersPerPeriod() == 2, "Non-admin should not be able to change winnersPerPeriod");
    }
}

