pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy: owner = this, so address(this) is admin and can addPoints
        // First, call addPoints to set some state (this is allowed by admin)
        c.addPoints(1, 100);

        // Now, prank as a non-admin (address(1))
        vm.prank(address(1));
        // Try to update winnersPerPeriod; in reference, the isAdmin check reverts
        // In buggy version, it succeeds
        bool success = false;
        try c.updateWinnersPerPeriod(5) {
            success = true;
        } catch {
            success = false;
        }

        // If the call succeeded, winnersPerPeriod will be 5; if reverted, it remains 2
        assertTrue(success == false || (c.winnersPerPeriod() == 5 ? false : true));
        // Actually, we want to assert that the reference holds (call reverts) and bug fails (call succeeds)
        // So we assert that the call reverts (success == false). In reference it reverts, in bug it succeeds -> false.
        // Thus the assertion passes on reference and fails on bug.
        assertTrue(!success);
    }
}

